-- 0102 part 3/3: Crompton import - electrical FMEG scope, in-stock,
-- Rs 300-50,000. Source: https://www.crompton.co.in Shopify products.json, scraped 2026-08-09.
-- 47 rows in this part. Run parts IN ORDER (variant children reference
-- their parent row). Pricing: store selling price -2%; MRP = compare_at_price.
-- brand_sku = "handle::variantId" (the Shopify sync adapter's per-variant code).
-- After the LAST part: "Rebuild mappings now" in /admin/compare.
on conflict (id) do nothing;

-- Crompton as an own-brand price source: the competitor sync auto-maps
-- every Crompton product by brand_sku (handle::variantId) and auto-applies
-- our price at Rs 1 under the store's selling price (Havells rules).
  values ('crompton', 'Crompton', 'https://www.crompton.co.in', true, false, 15)
  on conflict (id) do update set enabled = true, site_url = excluded.site_url;
